import { Component, AfterViewInit, ViewChild, ElementRef } from '@angular/core';
import { routes } from 'src/app/core/helpers/routes';
import { users, tickets, messages } from 'src/app/shared/model/page.model';
import { DataService, apiResultFormat } from 'src/app/core/core.index';
import { PaginationService } from 'src/app/shared/shared.index';
import Swal from 'sweetalert2';

@Component({
  selector: 'app-chat',
  templateUrl: './chat.component.html',
  styleUrls: ['./chat.component.scss'],
})
export class ChatComponent implements AfterViewInit {
  @ViewChild('chatContainer') private chatContainer!: ElementRef;

  public usersData: Array<any> = [];
  public ticketsData: Array<tickets> = [];
  public messagesData: Array<messages> = [];
  public selectedUser: {
    userId: number;
    name: string;
    profile_img_url: string;
  } | null = null;
  public selectedTicketId: number = 0;
  public selectedTicketMessage: string = '';
  public selectedTicketStatus: string = '';
  public showMessages: boolean = false;
  messageText: string = '';
  public routes = routes;
  pagination: any;
  filterSearchText: string = '';
  savedSearchText: string = '';
  page: number = 0;
  filterSelectedTicket: string = 'All';

  ticketFilters: { value: string; lable: string }[] = [
    { value: 'All', lable: 'All' },
    { value: 'Open', lable: 'Open' },
    { value: 'Closed', lable: 'Closed' },
  ];
  constructor(
    private data: DataService,
    private paginationService: PaginationService
  ) {
    this.getUsersData();
  }
  ngAfterViewInit(): void {
    this.scrollToBottom();
  }

  scrollToBottom(): void {
    setTimeout(() => {
      this.chatContainer.nativeElement.scrollTop =
        this.chatContainer.nativeElement.scrollHeight;
    }, 100);
  }
  private getUsersData(): void {
    this.data
      .getMessagesUsers(
        this.page,
        this.savedSearchText,
        this.filterSelectedTicket
      )
      .subscribe((apiRes: any) => {
        this.usersData = [];

        apiRes.results.users.forEach((res: any, index: number) => {
          // Push data to the table array
          this.usersData.push({
            ...res.user,
            closed_tickets: res.closed_tickets,
            open_tickets: res.open_tickets,
          });
        });
        this.paginationService.setPaginationData(apiRes.results.pagination);
        this.pagination = this.paginationService.getPaginationData();
      });
  }

  onPageChange(page: number) {
    this.page = page;
    this.getUsersData();
  }
  public clearSearch(): void {
    this.filterSearchText = '';
    this.savedSearchText = '';
    this.getUsersData();
  }
  onSearchClick(): void {
    this.savedSearchText = this.filterSearchText;
    this.getUsersData();
  }
  filterTicketType(): void {
    this.getUsersData();
  }
  submitCloseTicket(): void {
    this.selectedTicketStatus = 'Closed';
    this.data.closeTicket(this.selectedTicketId).subscribe({
      next: (res) => {
        Swal.fire({
          icon: 'success',
          title: 'Ticket Closed',
          text: 'The ticket has been closed successfully.',
          confirmButtonText: 'OK'
        });
      },
      error: (err) => {
        Swal.fire({
          icon: 'error',
          title: 'Failed to Close Ticket',
          text: 'Something went wrong. Please try again.',
          confirmButtonText: 'Retry'
        });
      }
    });
  }  
  private getTicketsData(userId: number, name: string): void {
    if (userId)
      this.data.getTicketsByUserId(userId).subscribe((apiRes: any) => {
        this.ticketsData = [];
        this.ticketsData = apiRes.results.tickets;
      });
  }
  private getMessagesData(ticketId: number): void {
    if (ticketId)
      this.data.getMessagesByTicketId(ticketId).subscribe((apiRes: any) => {
        this.messagesData = [];
        this.messagesData = apiRes.results.messages;
      });
  }
  selectUser(user: any): void {
    this.getTicketsData(user.user_id, user.first_name + ' ' + user.last_name);
    this.selectedUser = {
      userId: user.user_id,
      name: (user.first_name || '-') + ' ' + (user.last_name || '-'),
      profile_img_url: user.profile_img_url,
    };
  }
  selectTicket(ticket: any, event: string): void {
    console.log(ticket);
    if (event == 'show') {
      this.getMessagesData(ticket.ticket_id);
      this.selectedTicketId = ticket.ticket_id;
      this.selectedTicketMessage = ticket.subject;
      this.selectedTicketStatus = ticket.ticket_status;
      this.showMessages = true;
    } else {
      this.showMessages = false;
    }
  }
  submitMessage(): void {
    if (!this.messageText.trim()) {
      console.warn('Message cannot be empty');
      return;
    }
    if (this.messageText != '')
      this.data
        .submitMessage(this.selectedTicketId, this.messageText)
        .subscribe((apiRes: any) => {
          this.getMessagesData(this.selectedTicketId);
          this.messageText = '';
        });
  }
}
